begin;
select plan(9);
insert into auth.users(id,is_anonymous) values('48000000-0000-4000-8000-000000000101',false),('48000000-0000-4000-8000-000000000102',true);
insert into auth.sessions(id,user_id,created_at,updated_at) values('48000000-0000-4000-8000-000000000111','48000000-0000-4000-8000-000000000101',now(),now());
insert into public.families(id,name) values('48000000-0000-4000-8000-000000000141','Parent fanout test');
insert into public.family_members(family_id,user_id,role,status) values('48000000-0000-4000-8000-000000000141','48000000-0000-4000-8000-000000000101','owner','active');
insert into public.children(id,family_id,display_name) values('48000000-0000-4000-8000-000000000151','48000000-0000-4000-8000-000000000141','Fixture child');
insert into public.devices_public(id,family_id,child_id,display_name) values('48000000-0000-4000-8000-000000000161','48000000-0000-4000-8000-000000000141','48000000-0000-4000-8000-000000000151','Fixture device');
insert into private.device_security(device_id,auth_user_id,public_key_spki) values('48000000-0000-4000-8000-000000000161','48000000-0000-4000-8000-000000000102','fixture-key');
insert into private.parent_web_push_subscriptions(user_id,client_installation_id,endpoint,endpoint_hash,p256dh,auth) values('48000000-0000-4000-8000-000000000101','browser','https://push.test/parent-fanout',repeat('a',64),'key','auth');
create temporary table registrations as select * from private.harbor_register_parent_fcm('48000000-0000-4000-8000-000000000101','48000000-0000-4000-8000-000000000111','one','parent-fanout-one');
select * from private.harbor_register_parent_fcm('48000000-0000-4000-8000-000000000101','48000000-0000-4000-8000-000000000111','two','parent-fanout-two');
select * from private.harbor_update_device_desired_state('48000000-0000-4000-8000-000000000161','48000000-0000-4000-8000-000000000141','48000000-0000-4000-8000-000000000101','{"message":"sensitive domain content"}',0);
select is((select count(*) from private.notification_outbox),4::bigint,'one authoritative event creates child/browser/two parent intents');
select is((select count(*) from private.notification_outbox where target_ref ? 'parentFcmRegistrationId'),2::bigint,'each active parent installation has independent intent');
select is((select count(*) from private.notification_outbox where target_ref ? 'deviceId'),1::bigint,'legacy child intent remains independent');
select is((select count(*) from private.notification_outbox where transport='web_push'),1::bigint,'browser intent remains independent');
select is((select count(distinct route_payload->>'resourceId') from private.notification_outbox),1::bigint,'all transports share canonical event identity');
update private.device_desired_state set acknowledged_version=1;
select is((select count(*) from private.notification_outbox),4::bigint,'acknowledgment does not duplicate event intents');
select ok(not exists(select 1 from private.notification_outbox where route_payload::text like '%sensitive%'),'route boundaries exclude domain content');
select throws_ok($q$select private.harbor_enqueue_notification('mixed','fcm','{"deviceId":"48000000-0000-4000-8000-000000000161","parentFcmRegistrationId":"48000000-0000-4000-8000-000000000121","userId":"48000000-0000-4000-8000-000000000101"}','{"version":1,"kind":"device.state.changed"}')$q$,'22023','VALIDATION_FAILED','mixed parent/child target is rejected');
select ok(case when to_regprocedure('private.harbor_disable_parent_fcm(uuid,text,uuid,integer)') is null then false else not has_function_privilege('authenticated',to_regprocedure('private.harbor_disable_parent_fcm(uuid,text,uuid,integer)'),'EXECUTE') end,'token-generation cleanup is server-only');
select * from finish();rollback;
